    static int ParseInt(string s)
    {
        if (string.IsNullOrEmpty(s)) return 0;
        if (s.Contains("."))
            return (int)float.Parse(s, System.Globalization.CultureInfo.InvariantCulture);
        return int.Parse(s);
    }
    static float ParseFloat(string s)
    {
        if (string.IsNullOrEmpty(s)) return 0f;
        return float.Parse(s, System.Globalization.CultureInfo.InvariantCulture);
    }
    static T ParseEnum<T>(string s) where T : struct
    {
        if (string.IsNullOrEmpty(s)) return default;
        return (T)Enum.Parse(typeof(T), s, true);
    }
    static List<T> ParseList<T>(string s, Func<string, T> parseItem)
    {
        var result = new List<T>();
        if (string.IsNullOrEmpty(s)) return result;
        s = s.Trim();
        if (s.Length > 0 && s[0] == '{') s = s.Substring(1);
        if (s.Length > 0 && s[s.Length - 1] == '}') s = s.Substring(0, s.Length - 1);
        if (string.IsNullOrEmpty(s)) return result;
        foreach (var item in s.Split(','))
        {
            string t = item.Trim();
            if (!string.IsNullOrEmpty(t)) result.Add(parseItem(t));
        }
        return result;
    }
